// 1. Obtener entradas desde los argumentos pasados por la IA
const energia = typeof $json.energia !== 'undefined' ? parseFloat($json.energia) : 5.0;
const animo = typeof $json.animo !== 'undefined' ? parseFloat($json.animo) : 5.0;

// 2. Funciones de Pertenencia Triangulares (Fuzzificación)
function trimf(x, a, b, c) {
  if (x <= a || x >= c) return 0;
  if (x === b) return 1;
  if (x > a && x < b) return (x - a) / (b - a);
  if (x > b && x < c) return (c - x) / (c - b);
  return 0;
}

// Grados de pertenencia para ENERGÍA (0 a 10)
const mu_energia_baja  = trimf(energia, -1, 0, 5);
const mu_energia_media = trimf(energia, 2, 5, 8);
const mu_energia_alta  = trimf(energia, 5, 10, 11);

// Grados de pertenencia para ÁNIMO (0 a 10)
const mu_animo_bajo  = trimf(animo, -1, 0, 5);
const mu_animo_medio = trimf(animo, 2, 5, 8);
const mu_animo_alto  = trimf(animo, 5, 10, 11);

// 3. Base de Reglas Difusas (Inferencia T-Norma / MIN)
// Cada regla define un peso (disparo) y un BPM objetivo (Consecuente)
const reglas = [
  // R1: Energía Baja + Ánimo Bajo -> Muy calmado / Melancólico (BPM ~ 65)
  { peso: Math.min(mu_energia_baja, mu_animo_bajo), bpm: 65, perfil: "Lo-Fi / Slow Blues / Ambient acústico" },

  // R2: Energía Baja + Ánimo Alto -> Acústico relajado / Chill pop (BPM ~ 85)
  { peso: Math.min(mu_energia_baja, mu_animo_alto), bpm: 85, perfil: "Bossa Nova / Indie Acústico / Reggae suave" },

  // R3: Energía Media + Ánimo Bajo -> Rock reflexivo / Baladas lentas (BPM ~ 95)
  { peso: Math.min(mu_energia_media, mu_animo_bajo), bpm: 95, perfil: "Grunge acústico / Shoegaze / Post-Rock" },

  // R4: Energía Media + Ánimo Medio/Alto -> Ritmo equilibrado / Groove (BPM ~ 115)
  { peso: Math.min(mu_energia_media, Math.max(mu_animo_medio, mu_animo_alto)), bpm: 115, perfil: "Classic Rock / Funk / Synthpop" },

  // R5: Energía Alta + Ánimo Bajo -> Descarga / Catarsis (BPM ~ 140)
  { peso: Math.min(mu_energia_alta, mu_animo_bajo), bpm: 140, perfil: "Heavy Metal / Hard Rock / Punk" },

  // R6: Energía Alta + Ánimo Alto -> Máxima euforia / Fiesta / Cardio (BPM ~ 160)
  { peso: Math.min(mu_energia_alta, mu_animo_alto), bpm: 160, perfil: "Power Metal / Speed Metal / Drum & Bass / Hard Dance" }
];

// 4. Defuzzificación (Centro de Gravedad Ponderado / Sugeno)
let numerador = 0;
let denominador = 0;
let mejorPerfil = "Rock / Alternativo";
let maxPeso = -1;

for (const r of reglas) {
  numerador += r.peso * r.bpm;
  denominador += r.peso;
  if (r.peso > maxPeso) {
    maxPeso = r.peso;
    mejorPerfil = r.perfil;
  }
}

const bpmFinal = denominador > 0 ? Math.round(numerador / denominador) : 110;

// 5. Retornar perfil nítido (Crisp Output)
// 5. Retornar como texto estructurado (String)
return `BPM Objetivo: ${bpmFinal}. Perfil acústico: ${mejorPerfil}. Diagnóstico: Evaluado con Energía ${energia}/10 y Ánimo ${animo}/10. Pertenencia difusa calculó un BPM de ${bpmFinal}. Recomendación de búsqueda: ${mejorPerfil} con tempo cercano a ${bpmFinal} BPM.`;
